DO $review$
DECLARE v jsonb; s public.est_source_review%rowtype; q public.questions%rowtype; k public.question_keys%rowtype; a jsonb; qid uuid; p jsonb; pid uuid;
BEGIN
 FOR v IN SELECT value FROM jsonb_array_elements($payload$[{"id": "clean:MIX 034", "old_status": "ocr_screened_not_verified", "status": "ready", "question_id": "df0ef1f4-c1af-5904-8cd0-496032b01824", "stem": "Let \\(f(x)=\\sqrt{x+1}\\) and \\(g(x)=x^2-2\\). Which expression equals f(g(x)) wherever the composition is real?", "choices": [{"key": "A", "text": "\\(x^2+1\\)"}, {"key": "B", "text": "\\(x-1\\)"}, {"key": "C", "text": "\\(\\sqrt{(x-1)(x+1)}\\)"}, {"key": "D", "text": "\\(\\sqrt{x^2+1}\\)"}], "type": "mcq", "correct": "C", "explanation": "Substitute g(x) into f: f(g(x))=√[(x²−2)+1]=√(x²−1)=√[(x−1)(x+1)]. Its real domain is x≤−1 or x≥1.", "topic": "Functions, Transformations & Graphs", "note": "Recovered radical spans and included the real-domain qualification.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 437, "extra_sources": []}, {"id": "clean:MIX 035", "old_status": "ocr_screened_not_verified", "status": "ready", "question_id": "a03b6355-dfd5-56ea-9e27-1ac994c189f1", "stem": "Which describes the complete solution set of −3<4x−7<2?", "choices": [{"key": "A", "text": "x<1 or x>2.25"}, {"key": "B", "text": "x<1 or x<2.25"}, {"key": "C", "text": "x<1 and x>2.25"}, {"key": "D", "text": "x>1 and x<2.25"}], "type": "mcq", "correct": "D", "explanation": "Add 7 to each part: 4<4x<9. Divide by positive 4: 1<x<9/4=2.25. Both bounds are strict.", "topic": "Algebra Foundations, Equations & Inequalities", "note": "Original inequalities and D are strict. Asked for the complete solution set, since a weaker statement in B is also implied but not equivalent.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 437, "extra_sources": []}, {"id": "clean:MIX 036", "old_status": "ocr_screened_not_verified", "status": "ready", "question_id": "080c9bfe-61ac-520d-9515-06ae41418984", "stem": "If (x−4y)²=16, what are the possible values of 3(x−4y)?", "choices": [{"key": "A", "text": "3"}, {"key": "B", "text": "4"}, {"key": "C", "text": "9"}, {"key": "D", "text": "−12 and 12"}], "type": "mcq", "correct": "D", "explanation": "Taking square roots gives x−4y=−4 or 4. Multiplying by 3 gives −12 or 12. Both possibilities are attainable.", "topic": "Algebra Foundations, Equations & Inequalities", "note": "Corrected D to include both signs; the original 12 alone incorrectly discards the negative root without a sign condition.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 437, "extra_sources": []}, {"id": "clean:MIX 037", "old_status": "ocr_screened_not_verified", "status": "ready", "question_id": "41a4a33d-489b-5cfc-8997-cddf870f1a35", "stem": "Which describes the complete solution set of |4x+1|≤10?", "choices": [{"key": "A", "text": "x=2.25"}, {"key": "B", "text": "x≤2.25 or x≥2.75"}, {"key": "C", "text": "x≤2.25 and x≥−2.75"}, {"key": "D", "text": "x=2.75"}], "type": "mcq", "correct": "C", "explanation": "The absolute-value inequality is equivalent to −10≤4x+1≤10. Subtract 1 and divide by 4: −11/4≤x≤9/4, or −2.75≤x≤2.25.", "topic": "Algebra Foundations, Equations & Inequalities", "note": "Verified weak inequality signs in the source; OCR had changed them to strict signs.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 437, "extra_sources": []}, {"id": "clean:MIX 038", "old_status": "ocr_screened_not_verified", "status": "ready", "question_id": "c3bef890-ea7d-5956-9ac2-a1b3ceffeb36", "stem": "A person stands vertically on level ground with height 1.82 m. The straight distance from the top of the person to the tip of the shadow is 4.45 m. What is the shadow’s length in meters, rounded to two decimal places?", "choices": [], "type": "grid_in", "correct": "4.06", "explanation": "Height and shadow are perpendicular legs of a right triangle with hypotenuse 4.45. The shadow is √(4.45²−1.82²)=√16.4901≈4.0608004 m, or 4.06 m.", "topic": "Coordinate Geometry & Circles", "note": "Clarified the original “length of his sight” as the hypotenuse and stated level-ground geometry. Numeric response replaces the incomplete option list.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 438, "extra_sources": []}, {"id": "clean:MIX 039", "old_status": "ocr_screened_not_verified", "status": "ready", "question_id": "d5d780a9-2a82-5055-bab2-bbfa502c2175", "stem": "The table records tickets and revenue for a game. Each ticket within a section has the same price. What is the price of one ticket in section A?", "choices": [{"key": "A", "text": "$35"}, {"key": "B", "text": "$30"}, {"key": "C", "text": "$50"}, {"key": "D", "text": "$130"}], "type": "mcq", "correct": "A", "explanation": "Section A earned $8750 from 250 tickets, so each ticket costs 8750/250=$35.", "topic": "Statistics, Probability & Data Analysis", "note": "Recovered every entry of the shared table from pages 438, 439, and 272. Isolated Q26 and separately published Q27.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 438, "extra_sources": [], "assets": {"html": "<table><tr><th>Section</th><th>Available</th><th>Sold</th><th>Revenue ($)</th></tr><tr><th>VIP</th><td>100</td><td>80</td><td>10400</td></tr><tr><th>A</th><td>350</td><td>250</td><td>8750</td></tr><tr><th>B</th><td>350</td><td>288</td><td>8640</td></tr><tr><th>C</th><td>120</td><td>110</td><td>5500</td></tr></table>"}, "parts": [{"label": "Q27", "question_id": "6aa09f5f-f431-58c6-bc47-586c87f39751", "stem": "Using the ticket table, how much do six VIP tickets cost?", "choices": [{"key": "A", "text": "$498"}, {"key": "B", "text": "$1150"}, {"key": "C", "text": "$1500"}, {"key": "D", "text": "$780"}], "type": "mcq", "correct": "D", "explanation": "VIP tickets earned $10400 for 80 tickets, so one costs 10400/80=$130. Six cost 6·130=$780.", "topic": "Statistics, Probability & Data Analysis", "note": "Split from the original shared crop; original PDF visually checked and solution independently verified.", "assets": {"html": "<table><tr><th>Section</th><th>Available</th><th>Sold</th><th>Revenue ($)</th></tr><tr><th>VIP</th><td>100</td><td>80</td><td>10400</td></tr><tr><th>A</th><td>350</td><td>250</td><td>8750</td></tr><tr><th>B</th><td>350</td><td>288</td><td>8640</td></tr><tr><th>C</th><td>120</td><td>110</td><td>5500</td></tr></table>"}}]}]$payload$::jsonb) LOOP
  SELECT * INTO s FROM public.est_source_review WHERE id=v->>'id' FOR UPDATE;
  IF s.id IS NULL THEN RAISE EXCEPTION 'Missing source %',v->>'id'; END IF;
  IF EXISTS(SELECT 1 FROM public.audit_log WHERE action=coalesce(v->>'audit_action','source_review_20260928') AND target_id=s.id) THEN CONTINUE; END IF;
  IF s.review_status<>v->>'old_status' THEN RAISE EXCEPTION 'Source status changed %',s.id; END IF;
  qid=nullif(v->>'question_id','')::uuid;
  IF v->>'status'='ready' AND qid IS NOT NULL AND EXISTS(SELECT 1 FROM public.exams e JOIN public.attempts t ON t.exam_id=e.id
      WHERE qid=ANY(e.question_ids) AND t.status='in_progress' AND t.deadline_at>now()) THEN
   INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES('source_review_deferred_20260928','source_review',s.id,jsonb_build_object('reason','Active exam','proposed',v));
   CONTINUE;
  END IF;
  SELECT * INTO q FROM public.questions WHERE id=qid FOR UPDATE;
  SELECT * INTO k FROM public.question_keys WHERE question_id=qid FOR UPDATE;
  IF q.id IS NOT NULL AND v ? 'before' AND
    (q.stem IS DISTINCT FROM v->'before'->>'stem' OR q.choices IS DISTINCT FROM v->'before'->'choices' OR
     k.correct IS DISTINCT FROM v->'before'->'correct' OR k.explanation IS DISTINCT FROM v->'before'->>'explanation') THEN
    RAISE EXCEPTION 'Concurrent live question change %',qid;
  END IF;
  INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES(coalesce(v->>'audit_action','source_review_20260928'),'source_review',s.id,
    jsonb_build_object('before_source',to_jsonb(s),'before_question',to_jsonb(q),'before_key',to_jsonb(k),'decision',v-'assets'-'before'));
  IF v->>'status'='ready' THEN
   IF v->>'type'='mcq' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v->'choices') c WHERE c->>'key'=v->'correct'#>>'{}') THEN RAISE EXCEPTION 'Invalid key %',s.id; END IF;
   IF v->>'type'='grid_in' AND NOT public.answer_matches('grid_in',CASE WHEN jsonb_typeof(v->'correct')='array' THEN v->'correct'->0 ELSE v->'correct' END,v->'correct') THEN RAISE EXCEPTION 'Grader rejects %',s.id; END IF;
   a=(coalesce(q.assets,'{}'::jsonb)-'release_hold_reason')||coalesce(v->'assets','{}'::jsonb)||jsonb_build_object(
    'verified_release','2026-09-28-independent-solution-and-source-check','answer_review','2026-09-28-independent-solution-and-source-check',
    'verification_note',v->>'note','source_review_id',s.id,'verification_source',s.source_document||' page '||s.source_page);
   IF q.id IS NULL THEN
    a=a||jsonb_build_object('source','reviewed-bank-20260928','source_code',s.source_code,'source_document',s.source_document,'source_page',s.source_page);
    INSERT INTO public.questions(id,track_id,topic,difficulty,type,stem,choices,assets)
     VALUES(qid,s.track_id,v->>'topic','medium',v->>'type',v->>'stem',v->'choices',a);
    INSERT INTO public.question_keys(question_id,correct,explanation) VALUES(qid,v->'correct',v->>'explanation');
   ELSE
    UPDATE public.questions SET topic=v->>'topic',type=v->>'type',stem=v->>'stem',choices=v->'choices',assets=a WHERE id=qid;
    UPDATE public.question_keys SET correct=v->'correct',explanation=v->>'explanation' WHERE question_id=qid;
   END IF;
   FOR p IN SELECT value FROM jsonb_array_elements(coalesce(v->'parts','[]'::jsonb)) LOOP
    pid=(p->>'question_id')::uuid;
    IF EXISTS(SELECT 1 FROM public.questions WHERE id=pid) THEN RAISE EXCEPTION 'Split question already exists %',pid; END IF;
    IF p->>'type'='mcq' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p->'choices') c WHERE c->>'key'=p->'correct'#>>'{}') THEN RAISE EXCEPTION 'Invalid split key %',pid; END IF;
    IF p->>'type'='grid_in' AND NOT public.answer_matches('grid_in',CASE WHEN jsonb_typeof(p->'correct')='array' THEN p->'correct'->0 ELSE p->'correct' END,p->'correct') THEN RAISE EXCEPTION 'Invalid split numeric key %',pid; END IF;
    INSERT INTO public.questions(id,track_id,topic,difficulty,type,stem,choices,assets)
     VALUES(pid,s.track_id,coalesce(p->>'topic',v->>'topic'),'medium',p->>'type',p->>'stem',p->'choices',coalesce(p->'assets','{}'::jsonb)||jsonb_build_object(
      'source','reviewed-bank-20260928','source_review_id',s.id,'source_code',s.source_code||':'||(p->>'label'),'source_document',s.source_document,'source_page',s.source_page,
      'verified_release','2026-09-28-independent-solution-and-source-check','answer_review','2026-09-28-independent-solution-and-source-check','verification_note',p->>'note'));
    INSERT INTO public.question_keys(question_id,correct,explanation) VALUES(pid,p->'correct',p->>'explanation');
   END LOOP;
  END IF;
  UPDATE public.est_source_review SET review_status=v->>'status',question_id=coalesce(qid,question_id),
   worked_answer=coalesce(v->'correct',worked_answer),duplicate_of=coalesce(v->>'duplicate_of',duplicate_of),
   review_note='Rechecked 2026-09-28. '||coalesce(v->>'note','')||CASE WHEN v ? 'explanation' THEN E'\nWorked solution: '||(v->>'explanation') ELSE '' END,
   updated_at=now() WHERE id=s.id;
  IF v ? 'parts' THEN UPDATE public.est_source_review SET review_note=review_note||E'\nAdditional separately published questions: '||(SELECT string_agg((partrow.value->>'label')||': '||(partrow.value->>'question_id')||'. '||(partrow.value->>'explanation'),E'\n') FROM jsonb_array_elements(v->'parts') partrow(value)) WHERE id=s.id; END IF;
 END LOOP;
END;
$review$;
SELECT count(*) applied_source_decisions FROM public.audit_log WHERE action='source_review_20260928';
